async function evaluate(source, userGesture = false) { return win.webContents.executeJavaScript(source, userGesture); }
async function toggleTerminalFullscreen(active, action = () => evaluate("document.getElementById('term-fullscreen').click()", true)) {
  // macOS menyelesaikan animasi native setelah fullscreenchange pada DOM.
  const transition = process.platform === 'darwin' && !domFullscreenOnly ? new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`Native fullscreen transition timed out: ${active}`)), 10000);
    win.once(active ? 'enter-full-screen' : 'leave-full-screen', () => { clearTimeout(timer); resolve(); });
  }) : null;
  if (domFullscreenOnly) await evaluate("window.fixtureFullscreenChange = new Promise((resolve,reject) => { const changed = () => { clearTimeout(timer); resolve(true); }; const timer = setTimeout(() => { document.removeEventListener('fullscreenchange',changed); reject(new Error('DOM fullscreen transition timed out')); },10000); document.addEventListener('fullscreenchange',changed,{once:true}); }); true");
  await action();
  if (transition) await transition;
  if (domFullscreenOnly) await evaluate('window.fixtureFullscreenChange');
}
async function until(expression) {
  for (let i = 0; i < 100; i++) {
    if (await evaluate(expression)) return;
    await new Promise((resolve) => setTimeout(resolve, 30));
  }
  throw new Error(`Timeout: ${expression}`);
}
async function check(label, source) {
  assert.equal(await evaluate(source), true, label);
  tests++;
  console.log(`PASS ${label}`);
}
async function screenshot(name) {
  if (!output) return;
  fs.mkdirSync(output, { recursive: true });
  // Beri compositor kesempatan melukis tema/layout terbaru sebelum capturePage.
  await evaluate("new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)))");
  await new Promise((resolve) => setTimeout(resolve, 200));
  fs.writeFileSync(path.join(output, `${name}.png`), (await win.webContents.capturePage()).toPNG());
}

